async function loadCodex(force=false){if(S.codex&&!force)return S.codex;S.codex=await api('/api/admin/codex');renderCodexTargets();return S.codex}
function renderCodexTargets(){const list=$('#codexTargetList');if(!list||!S.codex)return;const q=($('#codexTargetSearch')?.value||'').trim().toLowerCase();let html='';for(const c of S.codex.categories||[]){if(!q||c.title.toLowerCase().includes(q))html+=`<button type="button" class="codex-target-row category ${S.codexTarget?.type==='category'&&S.codexTarget.key===c.slug?'active':''}" data-type="category" data-key="${esc(c.slug)}"><span class="codex-target-icon">▧</span><div><strong>${esc(c.title)}</strong><small>Chapter · ${(c.pages||[]).length} entries</small></div></button>`;for(const p of c.pages||[]){if(q&&!p.title.toLowerCase().includes(q)&&!c.title.toLowerCase().includes(q))continue;html+=`<button type="button" class="codex-target-row entry ${S.codexTarget?.type==='page'&&S.codexTarget.key===p.slug?'active':''}" data-type="page" data-key="${esc(p.slug)}"><span class="codex-target-icon">${p.presentation?.visibility==='hidden'?'◌':p.presentation?.visibility==='teaser'?'◇':'·'}</span><div><strong>${esc(p.title)}</strong><small>${esc(c.title)}${p.presentation?.featured?' · Featured':''}</small></div></button>`}}list.innerHTML=html||'<div class="marker-directory-empty">No matching codex entries.</div>';$$('.codex-target-row').forEach(b=>b.onclick=()=>selectCodexTarget(b.dataset.type,b.dataset.key))}
