async function saveCodexPresentation(){if(!S.codexTarget)return;const target={...S.codexTarget};const presentation=collectCodexPresentation();try{await api('/api/admin/codex/presentation',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({target_type:target.type,target_key:target.key,presentation})});S.codex=null;await loadCodex();selectCodexTarget(target.type,target.key);refreshWikiPreview();toast('Codex presentation saved')}catch(e){toast(e.message,'error')}}
